#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define B 255
#define MAXD 6000   // max base-255 digits for low/range

typedef struct {
    unsigned char d[MAXD];
    int n;             // number of limbs (base 255), little-endian
} Big;

void bi_zero(Big *a){ a->n=1; a->d[0]=0; }
void bi_set_u32(Big *a, unsigned int x){ int i=0; while(x){a->d[i++]=x%255;x/=255;} a->n= i?i:1; if(a->n==1) a->d[0]= (a->n==1?a->d[0]:a->d[0]); }

// a *= small (0..2^31)
void bi_mul_small(Big *a, unsigned int m){
    if(m==0){ bi_zero(a); return; }
    unsigned long long carry=0;
    int i;
    for(i=0;i<a->n;i++){ unsigned long long v=(unsigned long long)a->d[i]*m+carry; a->d[i]=v%255; carry=v/255; }
    while(carry){ a->d[a->n++]=(unsigned char)(carry%255); carry/=255; }
}

// a += small
void bi_add_small(Big *a, unsigned int s){
    int i=0; unsigned long long carry=s;
    while(carry){ unsigned long long v=a->d[i]+carry; a->d[i]=v%255; carry=v/255; i++; if(i>=a->n) a->n=i+1; }
}

// a += b (big), result in a
void bi_add(Big *a, const Big *b){
    int carry=0, i;
    int maxn = a->n>b->n?a->n:b->n;
    for(i=0;i<maxn;i++){
        int va = i<a->n?a->d[i]:0;
        int vb = i<b->n?b->d[i]:0;
        int s = va+vb+carry;
        if(i>=MAXD-1){fprintf(stderr,"MAXD\n");exit(1);}
        a->d[i]=s%255; carry=s/255;
    }
    if(carry){ a->d[maxn++]=(unsigned char)carry; }
    a->n=maxn;
}

// a /= m (small), remainder returned; a=none
unsigned int bi_div_small(Big *a, unsigned int m){
    if(m==0) {fprintf(stderr,"div0\n");exit(1);}
    unsigned long long rem=0;
    int i;
    for(i=a->n-1;i>=0;i--){ unsigned long long cur=rem*255+a->d[i]; a->d[i]=(unsigned char)(cur/m); rem=cur%m; }
    while(a->n>1 && a->d[a->n-1]==0) a->n--;
    return (unsigned int)rem;
}

static Big low, range, splitB;

static unsigned int cc[2000000];

static int N=0;

static void renorm(void){
    while(1){
        // need range < 255 check on big
        // range < 255 iff n==1 and d0<255
        if(range.n>1 || range.d[0]>=255) break;
        // range*=255
        for(int i=0;i<range.n;i++) range.d[i]*=255;  // each digit<255*255 fits
        // normalize range
        {
            unsigned long long carry=0;
            for(int i=0;i<range.n;i++){ unsigned long long v=range.d[i]+carry; range.d[i]=v%255; carry=v/255; }
            while(carry){ range.d[range.n++]=carry%255; carry/=255; }
        }
        // low *= 255
        for(int i=0;i<low.n;i++) low.d[i]*=255;
        {
            unsigned long long carry=0;
            for(int i=0;i<low.n;i++){ unsigned long long v=low.d[i]+carry; low.d[i]=v%255; carry=v/255; }
            while(carry){ low.d[low.n++]=carry%255; carry/=255; }
        }
        N++;
    }
}

void put_bit(int ctx, int bit){
    renorm();
    unsigned int c0=cc[ctx*2], c1=cc[ctx*2+1];
    // split = range*(c0+1)/(c0+c1+2)
    // copy range to splitB
    splitB=range;
    bi_mul_small(&splitB, c0+1);
    bi_div_small(&splitB, c0+c1+2);
    if(bit){
        bi_add(&low, &splitB);
        // range -= splitB
        // subtract big-splitB from range
        int borrow=0;
        for(int i=0;i<splitB.n;i++){ int v=range.d[i]-splitB.d[i]-borrow; if(v<0){v+=255;borrow=1;}else borrow=0; range.d[i]=(unsigned char)v; }
        for(int i=splitB.n;i<range.n;i++){ int v=range.d[i]-borrow; if(v<0){v+=255;borrow=1;}else borrow=0; range.d[i]=(unsigned char)v; }
        while(range.n>1 && range.d[range.n-1]==0) range.n--;
        cc[ctx*2+1]++;
    } else {
        range=splitB;
        cc[ctx*2]++;
    }
}

void emit_get_integer_bits(int value,int tmp0,int ctx0){
    int subtract=1<<tmp0;
    long long target=(long long)value+subtract;
    int ctx=ctx0*99;
    // find z
    int z=0;
    while(!(( (1LL<<(tmp0+z)) <= target) && (target < (1LL<<(tmp0+z+1))))) z++;
    int curTmp=tmp0;
    for(int k=0;k<z;k++){ put_bit(curTmp+1+ctx,0); curTmp++; }
    put_bit(curTmp+1+ctx,1); curTmp++;
    int n_bits=curTmp-1; // tmp--
    long long lower=target-(1LL<<(tmp0+z));
    for(int k=n_bits-1;k>=0;k--){ put_bit(ctx,(lower>>k)&1); }
}

