    // read data
    FILE*f=fopen("/app/data.txt","rb");
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    unsigned char*data=malloc(sz+1);
    fread(data,1,sz,f); fclose(f);
    // LZ parse: greedy
    int*cmds=malloc(sizeof(int)*sz*3);
    int*cmdlen=malloc(sizeof(int)*sz);
    int ccount=0;
    int i=0;
    while(i<sz){
        int bestLen=0,bestDist=0;
        int maxd = i<3000?i:3000;
        for(int d=1;d<=maxd;d++){
            int pos=i-d; int l=0;
            while(i+l<sz && data[pos+l]==data[i+l]) l++;
            if(l>bestLen){ bestLen=l; bestDist=d; }
        }
        if(bestLen>=2){ cmds[ccount]=bestDist; cmdlen[ccount]=bestLen; ccount++; i+=bestLen; }
        else { cmds[ccount]=-1; cmdlen[ccount]=data[i]; ccount++; i++; }
    }
    bi_zero(&low); bi_set_u32(&range,1);
    // j = ccount
    emit_get_integer_bits(ccount,9,0);
    int idx=0;
    for(int c=0;c<ccount;c++){
        if(cmds[c]>=0){
            int dist=cmds[c], length=cmdlen[c];
            put_bit(1,1);
            emit_get_integer_bits(dist-1,5,2);
            emit_get_integer_bits(length-1,2,3);
        } else {
            int byte=cmdlen[c];
            put_bit(1,0);
            if(byte>=0){ put_bit(8,0); emit_get_integer_bits(byte,4,9); }
            else { put_bit(8,1); emit_get_integer_bits(-byte,4,9); }
        }
    }
    // finalize
    int NN=N;
    // C = low + range/2 . range/2 = range >>1
    Big half=range; bi_div_small(&half,2);
    Big C=low; bi_add(&C,&half);
    // S = sum_{0..NN-1} B^k
    Big S; bi_zero(&S);
    { Big pw; bi_set_u32(&pw,1);
      for(int k=0;k<NN;k++){ bi_add(&S,&pw); bi_mul_small(&pw,255); } }
    // bytes_num = C + S
    bi_add(&C,&S);
    // ensure < B^NN and >=0
    int out[MAXD];
    for(int k=0;k<NN;k++){ unsigned int r=bi_div_small(&C,255); out[k]=r; }
    // write reversed as bytes = coeff+1
    FILE*fo=fopen("/app/data.comp","wb");
    for(int k=NN-1;k>=0;k--) fputc(out[k]+1, fo);
    fclose(fo);
    fprintf(stderr,"N=%d bytes=%d size=%ld\n",NN,NN,sz);
    return 0;
}

